def find_sequence(n, k):
    if n < k or n % k != 0:
        return -1

    max_gcd = 1
    for i in range(1, k + 1):
        if n % i == 0:
            current_gcd = gcd(max_gcd, i)
            if current_gcd > max_gcd:
                max_gcd = current_gcd
                sequence = [i]
            elif current_gcd == max_gcd:
                sequence.append(i)

    if len(sequence) != k:
        return -1

    return sequence

