import math

def find_sequence(n, k):
    if n < k:
        return -1

    gcd = n // k
    remainder = n % k

    if remainder == 0:
        return [gcd] * k
    elif remainder > k:
        return -1
    else:
        result = [gcd + 1] * remainder + [gcd] * (k - remainder)
        return result

