def find_sequence(n, k):
    if n < k * (k + 1) // 2:
        return -1
    if n % k == 0:
        base = n // k
        return [base + i for i in range(k)]
    else:
        target_gcd = n // k
        for start in range(1, n // k + 1):
            seq = [start + i * target_gcd for i in range(k)]
            if sum(seq) == n:
                return seq
        return -1

