from typing import List

def find_sequence(n: int, k: int) -> List[int]:
    if n < k or k == 1:
        return [-1]

    gcd = 1
    while n > 0 and k > 0:
        if n % k == 0:
            return [i * gcd for i in range(1, k + 1)]
        gcd += 1

    return [-1]

